        if self._id == 0:
            _self = 0x00
        else:
            _self = 0x02    
        try:           
            i2c.write(0x20, bytearray([_self, d, s]))
        except:
            print("Please switch on mbRobot!")
            while True:
                pass

    def rotate(self, s):
        v = abs(s)
        v = v + 50 
        if s > 0:           
            self._w(0, v)    
        elif s < 0:           
            self._w(1, v) 
        else:   
            self._w(0, 0)    


